//! Independent byte-domain curve and zero-XP failure oracle for crab carving.
use gielinor_world::{grinding,tool_crafting::{Job,Recipe,Failure},inventory::{Inventory,Catalog,Item,StackType},stats::Stats,npc::RandomSource};
const PROFILES:[(i32,i32,i32);2]=[(7538,7539,7541),(7536,7537,7540)];
struct Draw{value:u32,calls:usize}impl RandomSource for Draw{fn below(&mut self,n:u32)->u32{assert_eq!(n,256);self.calls+=1;self.value}}
fn fixture(i:usize)->(Job,Inventory,Catalog,Stats){let(raw,out,broken)=PROFILES[i];let mut inv=Inventory::new(28,StackType::Normal,false);for s in 0..28{inv.restore_slot(s,Some(Item{id:1931,count:1,vars:0})).unwrap();}for s in[0,1]{inv.restore_slot(s,Some(Item{id:1755,count:1,vars:0})).unwrap();}for s in[4,17]{inv.restore_slot(s,Some(Item{id:raw,count:1,vars:0})).unwrap();}let mut stats=Stats::default();stats.set_base(12,99);stats.set_current(12,99);stats.set_fine_xp(12,130344311).unwrap();let job=Job{recipe:Recipe{exchange:grinding::Recipe{tool:1755,input:raw,output:out,members:true,animation:Some(1280)},level:15,xp_tenths:325,ticks:3,name:"independent crab",action:"carve",failure:Some(Failure{output:broken,xp_tenths:0,low:40,high:240,message:"You accidentally break the crab material."})},tool_slot:0,input_slot:17};(job,inv,Catalog::default(),stats)}
fn threshold(level:i32)->u32{let l=level.clamp(1,99);((40*98+200*(l-1)+49)/98+1).clamp(0,256) as u32}
#[test]
fn thirty_invalid_input_policy_or_credit_cases_refuse_before_rng(){let mut n=0;for i in 0..2{for mode in 0..15{let(mut job,mut inv,mut cat,mut stats)=fixture(i);let mut member=true;let mut rate=125;match mode{0=>{cat.dummy.insert(PROFILES[i].1);},1=>{cat.dummy.insert(PROFILES[i].2);},2=>{inv.restore_slot(17,Some(Item{id:PROFILES[i].0,count:1,vars:1})).unwrap();},3=>{inv.restore_slot(0,Some(Item{id:1755,count:1,vars:1})).unwrap();},4=>{inv.restore_slot(17,Some(Item{id:PROFILES[i].0,count:2,vars:0})).unwrap();},5=>{inv.restore_slot(0,Some(Item{id:1755,count:2,vars:0})).unwrap();},6=>member=false,7=>stats.set_current(12,14),8=>rate=0,9=>rate=-1,10=>job.recipe.failure.as_mut().unwrap().low=241,11=>job.recipe.failure.as_mut().unwrap().high=65536,12=>job.recipe.failure.as_mut().unwrap().low=-1,13=>job.recipe.failure.as_mut().unwrap().output=PROFILES[i].0,_=>job.recipe.exchange.output=1755}let before=(inv.clone(),stats.clone());let mut rng=Draw{value:255,calls:0};assert!(job.resolve(&inv,&cat,&stats,rate,member,&mut rng).is_err(),"profile{i} mode{mode}");assert_eq!(rng.calls,0);assert_eq!((inv,stats),before);n+=1;}}assert_eq!(n,30);}
